import UIKit

@main
class AppDelegate: UIResponder, UIApplicationDelegate {
    var window: UIWindow?
    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil) -> Bool {
        window = UIWindow(frame: UIScreen.main.bounds)
        window?.rootViewController = UIViewController()
        window?.makeKeyAndVisible()
        return true
    }
}

import XCTest

final class StandupTests: XCTestCase {

    let app = XCUIApplication(bundleIdentifier: "im.vector.app")

    func dumpHierarchy(_ name: String) {
        let path = "/tmp/\(name).txt"
        try? app.debugDescription.write(toFile: path, atomically: true, encoding: .utf8)
    }

    func testOpenRoomAndSearch() throws {
        app.launch()

        let room = app.staticTexts["Team Standup"].firstMatch
        XCTAssertTrue(room.waitForExistence(timeout: 60), "Team Standup row not visible")
        room.tap()

        Thread.sleep(forTimeInterval: 3)
        dumpHierarchy("hier_room")

        var searchTapped = false
        let candidates: [XCUIElement] = [
            app.buttons["Search"],
            app.buttons["search"],
            app.navigationBars.buttons["Search"]
        ]
        for c in candidates where c.exists {
            c.tap()
            searchTapped = true
            break
        }
        if !searchTapped {
            let pred = NSPredicate(format: "label CONTAINS[c] 'search' OR identifier CONTAINS[c] 'search'")
            let m = app.buttons.matching(pred).firstMatch
            if m.waitForExistence(timeout: 3) {
                m.tap()
                searchTapped = true
            }
        }
        Thread.sleep(forTimeInterval: 2)
        dumpHierarchy("hier_search")

        let field = app.searchFields.firstMatch
        if field.waitForExistence(timeout: 5) {
            field.tap()
            field.typeText("update")
        }
        Thread.sleep(forTimeInterval: 3)
        dumpHierarchy("hier_final")
        XCTAssertTrue(searchTapped, "search button not found")
    }
}

