import XCTest

final class StandupTests: XCTestCase {

    let app = XCUIApplication(bundleIdentifier: "im.vector.app")

    func dumpHierarchy(_ name: String) {
        let path = "/tmp/\(name).txt"
        try? app.debugDescription.write(toFile: path, atomically: true, encoding: .utf8)
    }

    func testOpenRoomAndSearch() throws {
        app.launch()

        let room = app.staticTexts["Team Standup"].firstMatch
        XCTAssertTrue(room.waitForExistence(timeout: 60), "Team Standup row not visible")
        room.tap()

        let gotIt = app.buttons["Got it"]
        if gotIt.waitForExistence(timeout: 10) {
            gotIt.tap()
        }

        let title = app.navigationBars["Team Standup"].staticTexts["Team Standup"]
        XCTAssertTrue(title.waitForExistence(timeout: 15), "room title not visible")
        title.tap()

        let searchRoom = app.staticTexts["Search room"]
        XCTAssertTrue(searchRoom.waitForExistence(timeout: 15), "Search room row not visible")
        searchRoom.tap()

        let field = app.searchFields.firstMatch
        XCTAssertTrue(field.waitForExistence(timeout: 15), "search field not visible")
        field.tap()
        field.typeText("update")

        Thread.sleep(forTimeInterval: 3)
        dumpHierarchy("hier_final")
    }
}

